pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedAmount, uint256 withdrawAmount) public {
        // Ensure the initial deposit does not overflow contract balance in practical terms
        seedAmount = bound(seedAmount, 1, address(c).balance + 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1, seedAmount);

        address owner = c.owner();
        // Fund the owner with some starting ETH so we can measure balance changes
        vm.deal(owner, 10 ether);

        // Give the contract some balance by sending from a random sender
        address funder = address(uint160(uint256(keccak256(abi.encode(seedAmount)))));
        vm.deal(funder, seedAmount);
        vm.prank(funder);
        (bool sent,) = address(c).call{value: seedAmount}("");
        require(sent, "funding failed");

        // Owner withdraws a portion via withdrawAll (the mutant withdraws 0 instead of the full balance)
        uint256 ownerBefore = owner.balance;
        uint256 contractBefore = address(c).balance;

        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerAfter = owner.balance;
        uint256 contractAfter = address(c).balance;

        // General rule: the owner's balance increase must equal the contract's balance before withdrawal
        // (since withdrawAll drains the entire contract). The buggy version transfers 0, so the increase is 0
        // while contractBefore is > 0, breaking the equality.
        assertTrue(ownerAfter - ownerBefore == contractBefore);
    }
}

