pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        uint256 balBefore = address(c).balance;
        bool ok;
        try c.sendMoney(target, value, data) { ok = true; } catch { ok = false; }
        // Reference: only owner can call sendMoney, so non-owner calls revert and balance unchanged.
        // Bug: require(msg.sender==address(0)) always fails, so call always reverts, balance unchanged.
        // But in reference, the owner CAN call it and change balance. So the difference appears when
        // the caller IS the owner: reference succeeds, bug reverts. However, test must be universal.
        // The general property: if the caller is not the owner, neither version should succeed, so balance unchanged.
        // If the caller IS the owner, reference succeeds (balance may drop), bug reverts (balance unchanged).
        // For the fuzzer to find the difference, we need to consider the owner case.
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore || (ok && msg.sender == c.owner()));
    }
}

