        // Conservation: owner gain + contract reduction + helper (none) = 0, meaning no ETH burned to zero address
        // In correct version: balAfterOwner == balBeforeOwner + amount and balAfterContract == balBeforeContract - amount.
        // In buggy version: balAfterOwner == balBeforeOwner (funds burned), balAfterContract == balBeforeContract - amount.
        // Therefore total ETH (owner + contract) decreases in buggy and stays same in correct.
        uint256 totalBefore = balBeforeOwner + balBeforeContract;
        uint256 totalAfter = balAfterOwner + balAfterContract;
        assertTrue(totalAfter == totalBefore, "ETH conservation violated");
    }
}

